self.KB_CONTENT["card:753517"]={"id":"card:753517","ty":"card","sourceId":"753517","title":"『產生分錄底稿-託外退費用』的作業目的為何？","ver":"iGP","topic":"貨單","keywords":["貨單","傳票","分錄","費用"],"y":"explain","answer":"在產生分錄底稿作業中之單據來源選擇託外退貨單費用時，自動開立傳票產生託外退貨單費用之分錄底稿資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
