self.KB_CONTENT["card:780423"]={"id":"card:780423","ty":"card","sourceId":"780423","title":"『進口費用自動結帳作業』中的『選擇結帳月份』為何？","ver":"GP4以上","topic":"應付","keywords":["應付","廠商","結帳","費用"],"y":"other","answer":"* 選擇結帳期間(2).依廠商結帳日時，須輸入結帳月份。輸入的月份須≧應付帳款現行年月。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
