self.KB_CONTENT["card:778789"]={"id":"card:778789","ty":"card","sourceId":"778789","title":"『生產計劃鎖定作業』的作業目的為何","ver":"GP4以上","topic":"生產","keywords":["生產","計劃","依據","控制"],"y":"explain","answer":"1.可以將生產計劃的全部或一部分以批次計劃碼設定為鎖定，以免重新計劃時有所更動或為局部發放的控制依據。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[778789,779478],"file":"kb-cards.jsonl"};
