self.KB_CONTENT["card:752107"]={"id":"card:752107","ty":"card","sourceId":"752107","title":"『多期比較財務報表』中的『』為何？","ver":"iGP","topic":"明細表","keywords":["明細表","科目","什麼","比較"],"y":"other","answer":"選擇列印種類* 分為1.不展統制/明細，2.展至統制帳戶及3.展至明細帳戶三種。* 不展統制/明細：在報表列印時，列印種類不論選擇什麼，都不展統制/明細。不展統制/明細表示依報表格式設定的科目列印。* 展至統制帳戶表示依報表格式設定的科目展至設定科目下的統制帳戶。* 展至明細帳戶表示依報表格式設定的科目展至設定科目下的明細科目。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
