self.KB_CONTENT["card:780496"]={"id":"card:780496","ty":"card","sourceId":"780496","title":"『進貨單與費用產生作業』中的『選擇報關單號』為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","單號","費用","報關"],"y":"other","answer":"* 可選擇報關單號區間。輸入時可按[F2]查詢報關單號資料，若空白表全部資料皆納入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
