self.KB_CONTENT["field:792046"]={"id":"field:792046","ty":"field","sourceId":"792046","title":"客戶品號","ver":"GP4以上","topic":"","keywords":[],"job":"出貨通知單建立作業","code":"TB031","answer":"* 客戶對於該商品所賦予之代號。* [F2]客戶品號資料查詢，若品號必須存於「客戶計價單頭檔」中，客戶品號、商品描述將自動顯示於後。* [F3]總店客戶品號資料查詢。","file":"fields.jsonl"};
