self.KB_CONTENT["field:792507"]={"id":"field:792507","ty":"field","sourceId":"792507","title":"付款條件","ver":"GP4以上","topic":"","keywords":[],"job":"保修工單建立作業","code":"TG020","answer":"* 可按(icon)或[F2]付款條件代號查詢。* 「性質」為2.託外時，此欄位才可輸入。","file":"fields.jsonl"};
