self.KB_CONTENT["field:784805"]={"id":"field:784805","ty":"field","sourceId":"784805","title":"選擇製造廠商","ver":"GP4以上","topic":"","keywords":[],"job":"資產購入清冊","code":"MB009","answer":"* 可勾選是否區間選擇。可自行選擇離散或區間。* 可點選(icon)或[F2]廠商資料查詢需列印之製造廠商代號範圍。若空白表全部。※ 資產明細帳","file":"fields.jsonl"};
