self.KB_CONTENT["field:780144"]={"id":"field:780144","ty":"field","sourceId":"780144","title":"修改金額","ver":"GP4以上","topic":"","keywords":[],"job":"預付購料變更建立作業","code":"TC012","answer":"* 將信用狀開狀修改金額輸入於此。* 此欄位必須大於等於零。* 預設修改自籌金額=修改金額×自籌比率×開狀匯率。","file":"fields.jsonl"};
