self.KB_CONTENT["field:758611"]={"id":"field:758611","ty":"field","sourceId":"758611","title":"輸入年月","ver":"iGP","topic":"","keywords":[],"job":"廠商ABC分析表","code":"","answer":"* 空白表全部資料，一般週期為月、季或年。* 所輸入之月份僅能輸入在 1~12 之間。","file":"fields.jsonl"};
self.KB_CONTENT["field:755674"]={"id":"field:755674","ty":"field","sourceId":"755674","title":"包裝數量","ver":"iGP","topic":"","keywords":[],"job":"暫出/入單建立作業","code":"TG028","answer":"* [F2]各庫庫存包裝量查詢，並顯示庫別資料。* [F3]批號庫存包裝量查詢，並顯示批號、庫別資料。* 若『共用參數設定作業』之數量表達方式欄位設定為「製造雙單位」且定重為「Y」者，數量取得回傳值傳入品號、包裝數量、包裝單位、單位。","file":"fields.jsonl"};
