self.KB_CONTENT["field:779023"]={"id":"field:779023","ty":"field","sourceId":"779023","title":"簽核狀態","ver":"GP4以上","topic":"","keywords":[],"job":"暫出/入歸還建立作業","code":"TH028","answer":"* 此欄位僅作顯示。簽核狀態碼類型區分為0.待處理、1.簽核中、2.退件、3.已核准、4.取消確認中、5.作廢中、6.取消作廢及N.不執行電子簽核中。","file":"fields.jsonl"};
